/** Throws `RangeError` when `timeZone` is not an IANA zone `Intl` recognises. */
export function assertTimeZone(timeZone: string): void {
  try {
    Intl.DateTimeFormat("en-US", { timeZone });
  } catch {
    throw new RangeError(`Unknown time zone: ${timeZone}`);
  }
}

type WallClock = {
  year: string;
  month: string;
  day: string;
  hour: number;
  minute: number;
  second: number;
};

function wallClock(date: Date, timeZone: string): WallClock {
  assertTimeZone(timeZone);
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(date);
  const read = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((part) => part.type === type)?.value ?? "0";
  let hour = Number(read("hour"));
  if (hour === 24) hour = 0;
  return {
    year: read("year"),
    month: read("month"),
    day: read("day"),
    hour,
    minute: Number(read("minute")),
    second: Number(read("second")),
  };
}

/** `YYYY-MM-DD` calendar date of `value` on the clock in `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const wall = wallClock(parseIso(value), timeZone);
  return `${wall.year}-${wall.month}-${wall.day}`;
}

function shiftCalendarDate(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const shifted = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, (day ?? 1) + days));
  const y = shifted.getUTCFullYear();
  const m = String(shifted.getUTCMonth() + 1).padStart(2, "0");
  const d = String(shifted.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** A `Date` that falls on the local calendar day `ymd` in `timeZone`. */
function referenceOnLocalDate(ymd: string, timeZone: string): Date {
  let probe = new Date(`${ymd}T12:00:00.000Z`);
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const local = localDate(toIsoTimestamp(probe), timeZone);
    if (local === ymd) return probe;
    const [ly, lm, ld] = local.split("-").map(Number);
    const [ty, tm, td] = ymd.split("-").map(Number);
    const delta =
      Date.UTC(ty ?? 0, (tm ?? 1) - 1, td ?? 1) -
      Date.UTC(ly ?? 0, (lm ?? 1) - 1, ld ?? 1);
    probe = new Date(probe.getTime() + delta);
  }
  return probe;
}

/**
 * UTC instant at which the calendar day containing `reference` began in
 * `timeZone`. Across a DST fold this is the first instant of that local date.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const target = localDate(toIsoTimestamp(reference), timeZone);
  let lo = reference.getTime() - 40 * HOUR_MS;
  let hi = reference.getTime() + 4 * HOUR_MS;
  while (localDate(toIsoTimestamp(new Date(lo)), timeZone) >= target) {
    lo -= DAY_MS;
  }
  while (localDate(toIsoTimestamp(new Date(hi)), timeZone) < target) {
    hi += DAY_MS;
  }
  while (hi - lo > 1) {
    const mid = Math.floor((lo + hi) / 2);
    if (localDate(toIsoTimestamp(new Date(mid)), timeZone) < target) lo = mid;
    else hi = mid;
  }
  return toIsoTimestamp(new Date(hi));
}

/**
 * Local midnight on the date `days` calendar days before the local date of
 * `reference`. Used by the retention sweep.
 */
export function localMidnightDaysBefore(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const today = localDate(toIsoTimestamp(reference), timeZone);
  const ymd = shiftCalendarDate(today, -days);
  return startOfLocalDay(referenceOnLocalDate(ymd, timeZone), timeZone);
}

/** True once the workspace calendar day that contains `dueAt` has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

