/**
 * Most recent local `hour:00:00` at or before `reference`. When the wall
 * clock repeats an hour, the later occurrence at or before `reference` wins.
 */
function mostRecentLocalHour(reference: Date, hour: number, timeZone: string): Date {
  let t = reference.getTime() - (reference.getTime() % 1000);
  const limit = t - 30 * HOUR_MS;
  while (t >= limit) {
    const date = new Date(t);
    const wall = wallClock(date, timeZone);
    if (wall.hour === hour && wall.minute === 0 && wall.second === 0) {
      return date;
    }
    t -= 1000;
  }
  throw new RangeError(`Could not resolve local hour ${hour} in ${timeZone}`);
}

/**
 * The window a digest covers. It ends at the most recent local `hour:00` at
 * or before `reference` (today's if that hour has passed, otherwise
 * yesterday's) and starts at the same local hour on the previous calendar
 * day, so a DST change makes the window 23 or 25 hours long.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const end = mostRecentLocalHour(reference, digestHourUtc, timeZone);
  const startDay = shiftCalendarDate(localDate(toIsoTimestamp(end), timeZone), -1);
  const start = mostRecentLocalHour(
    referenceOnLocalDate(shiftCalendarDate(startDay, 1), timeZone),
    digestHourUtc,
    timeZone,
  );
  // `referenceOnLocalDate` is noon-ish; walk from just after that local day
  // so a repeated hour resolves to the later occurrence, matching `end`.
  const startInstant = mostRecentLocalHour(
    new Date(parseIso(startOfLocalDay(referenceOnLocalDate(shiftCalendarDate(startDay, 1), timeZone), timeZone)).getTime() - 1000),
    digestHourUtc,
    timeZone,
  );

  return {
    start: toIsoTimestamp(startInstant.getTime() === start.getTime() ? startInstant : startInstant),
    end: toIsoTimestamp(end),
  };
}

