function mostRecentLocalHour(reference: Date, hour: number, timeZone: string): Date {
  let t = reference.getTime();
  const limit = t - 30 * HOUR_MS;
  while (t >= limit) {
    const date = new Date(t);
    const wall = wallClock(date, timeZone);
    if (wall.hour === hour && wall.minute === 0) {
      const exact = new Date(t - wall.second * 1000 - date.getMilliseconds());
      const check = wallClock(exact, timeZone);
      if (check.hour === hour && check.minute === 0 && check.second === 0) {
        return exact;
      }
    }
    t -= MINUTE_MS;
  }
  throw new RangeError(`Could not resolve local hour ${hour} in ${timeZone}`);
}

