/**
 * True during the hour when the workspace clock shows `digestHourUtc`.
 * Exported because the schedule decision is worth testing on its own,
 * without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  const hour = new Intl.DateTimeFormat("en-US", {
    timeZone: org.settings.timeZone,
    hourCycle: "h23",
    hour: "2-digit",
  }).formatToParts(now);
  const value = Number(hour.find((part) => part.type === "hour")?.value ?? "0");
  return (value === 24 ? 0 : value) === org.settings.digestHourUtc;
}

